import React, { useState, useEffect } from 'react';



import { Link } from 'react-router-dom';



import { getFeaturedProducts, getProductCategories, createSubscription } from '../services/api';



import { isAuthenticated } from '../util/auth';



import ProductCard from '../components/ProductCard';



import Toast from '../components/Toast';



import { useTheme } from '../context/ThemeContext';



import useToast from '../hooks/useToast';







const Home = () => {



  const [featuredProducts, setFeaturedProducts] = useState([]);



  const [categories, setCategories] = useState([]);



  const [loading, setLoading] = useState(true);



  const [currentSlide, setCurrentSlide] = useState(0);



  const [featureSlide, setFeatureSlide] = useState(0);



  const [showScrollTop, setShowScrollTop] = useState(false);



  const [featuredSlide, setFeaturedSlide] = useState(0);



  const [selectedPlan, setSelectedPlan] = useState(null);



  const [subscriptionModal, setSubscriptionModal] = useState(false);



  const [loadingSubscription, setLoadingSubscription] = useState(false);



  const [chatPopup, setChatPopup] = useState(false);



  const [selectedCategory, setSelectedCategory] = useState('all');



  const [viewMode, setViewMode] = useState('grid');



  const { isDarkMode } = useTheme();



  const { toasts, removeToast } = useToast();







  useEffect(() => {



    fetchData();



    // Handle scroll events

    const handleScroll = () => {

      setShowScrollTop(window.scrollY > 50);

    };



    window.addEventListener('scroll', handleScroll);



    



    // Auto-rotate hero slides



    const heroInterval = setInterval(() => {



      setCurrentSlide((prev) => (prev + 1) % 3);



    }, 4000);



    



    // Auto-rotate feature slides



    const featureInterval = setInterval(() => {



      setFeatureSlide((prev) => (prev + 1) % 3);



    }, 3000);



    



    return () => {



      clearInterval(heroInterval);



      clearInterval(featureInterval);



      window.removeEventListener('scroll', handleScroll);



    };



  }, []);







  const fetchData = async () => {



    try {



      setLoading(true);



      const [featuredRes, categoriesRes] = await Promise.all([



        getFeaturedProducts(),



        getProductCategories()



      ]);



      setFeaturedProducts(featuredRes.data);



      setCategories(categoriesRes.data);



    } catch (error) {



      console.error('Error fetching data:', error);



    } finally {



      setLoading(false);



    }



  };



  const scrollToTop = () => {



    window.scrollTo({



      top: 0,



      behavior: 'smooth'



    });



  };







  const handleSubscribe = async (planType) => {



    if (!userAuthenticated) {



      // Redirect to login if not authenticated



      window.location.href = '/login';



      return;



    }



    setSelectedPlan(planType);



    setSubscriptionModal(true);



  };







  const createSubscriptionHandler = async () => {



    if (!selectedPlan) return;



    



    try {



      setLoadingSubscription(true);



      



      const subscriptionData = {



        planType: selectedPlan,



        startDate: new Date().toISOString(),



        status: 'active'



      };



      



      const response = await createSubscription(subscriptionData);



      



      if (response.status === 201 || response.status === 200) {



        // Success - show success message



        alert('Subscription created successfully!');



        setSubscriptionModal(false);



        setSelectedPlan(null);



      } else {



        // Error - show error message



        alert(response.data?.message || 'Failed to create subscription');



      }



    } catch (error) {



      console.error('Subscription error:', error);



      alert('An error occurred while creating subscription');



    } finally {



      setLoadingSubscription(false);



    }



  };







  const getPlanDetails = (planType) => {



    const plans = {



      daily: {



        name: 'Daily Plan',



        price: 29,



        duration: 'day',



        features: [



          '500ml Fresh Milk Daily',



          '6:00 AM - 7:00 AM Delivery',



          'Pause Anytime',



          'Free Delivery'



        ]



      },



      weekly: {



        name: 'Weekly Plan',



        price: 189,



        duration: 'week',



        features: [



          '3.5L Milk Per Week',



          'Flexible Delivery Days',



          '10% Discount',



          'Free Delivery'



        ]



      },



      monthly: {



        name: 'Monthly Plan',



        price: 799,



        duration: 'month',



        features: [



          '15L Milk Per Month',



          'Custom Schedule',



          '20% Discount',



          'Free Delivery + Priority'



        ]



      }



    };



    



    return plans[planType] || null;



  };







  const userAuthenticated = isAuthenticated();







  return (



    <>

      <div className="fade-in">

      {/* Flipkart-Style Product Carousel Hero Section */}
      <section className={`relative py-8 ${isDarkMode ? 'bg-gray-900' : 'bg-gray-50'}`}>
        {/* Header */}
        <div className="px-4 mb-6">
          <div className="flex items-center justify-between">
            <h2 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              Fresh Dairy Products
            </h2>
            <Link 
              to="/products" 
              className={`text-sm font-medium ${isDarkMode ? 'text-blue-400 hover:text-blue-300' : 'text-blue-600 hover:text-blue-700'} transition-colors`}
            >
              View All →
            </Link>
          </div>
        </div>

        {/* Product Carousel Container */}
        <div className="relative overflow-hidden">
          <div id="carousel" className="flex gap-4 px-4 transition-transform duration-500 ease-in-out">
            {/* Product Cards */}
            {[
              {
                id: 1,
                name: "Fresh Cow Milk",
                price: "₹45",
                originalPrice: "₹60",
                discount: "25% OFF",
                image: "🥛",
                rating: "4.8",
                reviews: "2.3k",
                badge: "Bestseller",
                category: "milk"
              },
              {
                id: 2,
                name: "Amul Butter",
                price: "₹120",
                originalPrice: "₹150",
                discount: "20% OFF",
                image: "🧈",
                rating: "4.7",
                reviews: "1.8k",
                badge: "Popular",
                category: "butter"
              },
              {
                id: 3,
                name: "Farm Cheese",
                price: "₹80",
                originalPrice: "₹100",
                discount: "20% OFF",
                image: "🧀",
                rating: "4.9",
                reviews: "956",
                badge: "Premium",
                category: "cheese"
              },
              {
                id: 4,
                name: "Fresh Curd",
                price: "₹35",
                originalPrice: "₹45",
                discount: "22% OFF",
                image: "🥣",
                rating: "4.6",
                reviews: "1.2k",
                badge: "Fresh",
                category: "curd"
              },
              {
                id: 5,
                name: "Paneer Block",
                price: "₹95",
                originalPrice: "₹120",
                discount: "21% OFF",
                image: "🧈",
                rating: "4.8",
                reviews: "2.1k",
                badge: "Hot Deal",
                category: "paneer"
              },
              {
                id: 6,
                name: "Greek Yogurt",
                price: "₹65",
                originalPrice: "₹85",
                discount: "24% OFF",
                image: "🥛",
                rating: "4.7",
                reviews: "892",
                badge: "Healthy",
                category: "yogurt"
              },
              {
                id: 7,
                name: "Cream Cheese",
                price: "₹110",
                originalPrice: "₹140",
                discount: "21% OFF",
                image: "🧀",
                rating: "4.9",
                reviews: "1.5k",
                badge: "Premium",
                category: "cheese"
              },
              {
                id: 8,
                name: "Buttermilk",
                price: "₹25",
                originalPrice: "₹35",
                discount: "29% OFF",
                image: "🥛",
                rating: "4.5",
                reviews: "743",
                badge: "Summer Special",
                category: "milk"
              }
            ].map((product) => (
              <div
                key={product.id}
                onClick={() => window.location.href = `/product/${product.id}`}
                className={`flex-none w-64 rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:scale-105 cursor-pointer group ${isDarkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'}`}
              >
                {/* Product Image */}
                <div className="relative p-4 overflow-hidden rounded-t-xl">
                  {/* Badge */}
                  <div className={`absolute top-2 left-2 px-2 py-1 text-xs font-bold rounded-full z-10 ${
                    product.badge === 'Bestseller' ? 'bg-gradient-to-r from-orange-500 to-red-500 text-white' :
                    product.badge === 'Popular' ? 'bg-gradient-to-r from-blue-500 to-indigo-500 text-white' :
                    product.badge === 'Premium' ? 'bg-gradient-to-r from-purple-500 to-pink-500 text-white' :
                    product.badge === 'Fresh' ? 'bg-gradient-to-r from-green-500 to-emerald-500 text-white' :
                    product.badge === 'Hot Deal' ? 'bg-gradient-to-r from-red-500 to-orange-500 text-white' :
                    product.badge === 'Healthy' ? 'bg-gradient-to-r from-teal-500 to-cyan-500 text-white' :
                    'bg-gradient-to-r from-pink-500 to-rose-500 text-white'
                  }`}>
                    {product.badge}
                  </div>
                  
                  {/* Discount Badge */}
                  <div className="absolute top-2 right-2 bg-gradient-to-r from-red-500 to-pink-500 text-white text-xs font-bold px-2 py-1 rounded-full z-10 animate-pulse">
                    {product.discount}
                  </div>
                  
                  {/* Product Image with Hover Effect */}
                  <div className="flex justify-center items-center h-32 relative overflow-hidden">
                    <span className="text-6xl transform transition-transform duration-300 group-hover:scale-110">{product.image}</span>
                    {/* Quick View Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-end justify-center pb-2">
                      <span className="text-white text-xs font-medium">Quick View</span>
                    </div>
                  </div>
                </div>
                
                {/* Product Details */}
                <div className="p-4">
                  {/* Product Name */}
                  <h3 className={`font-semibold text-sm mb-2 line-clamp-2 group-hover:text-blue-500 transition-colors duration-200 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                    {product.name}
                  </h3>
                  
                  {/* Rating */}
                  <div className="flex items-center mb-2">
                    <div className="flex text-yellow-400">
                      {'★'.repeat(Math.floor(parseFloat(product.rating)))}
                      {'☆'.repeat(5 - Math.floor(parseFloat(product.rating)))}
                    </div>
                    <span className={`text-xs ml-1 ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                      ({product.reviews})
                    </span>
                  </div>
                  
                  {/* Price */}
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <span className="text-lg font-bold text-green-600">{product.price}</span>
                      <span className={`text-sm line-through ${isDarkMode ? 'text-gray-500' : 'text-gray-400'}`}>
                        {product.originalPrice}
                      </span>
                    </div>
                  </div>
                  
                  {/* Action Buttons */}
                  <div className="flex gap-2">
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        // Add to cart logic here
                        alert(`Added ${product.name} to cart!`);
                      }}
                      className={`flex-1 py-2 px-3 rounded-lg font-medium transition-all duration-200 transform hover:scale-105 ${
                        isDarkMode 
                          ? 'bg-gradient-to-r from-blue-600 to-blue-700 text-white hover:from-blue-700 hover:to-blue-800' 
                          : 'bg-gradient-to-r from-blue-500 to-blue-600 text-white hover:from-blue-600 hover:to-blue-700'
                      }`}
                    >
                      Add to Cart
                    </button>
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        // Add to wishlist logic here
                        alert(`Added ${product.name} to wishlist!`);
                      }}
                      className={`p-2 rounded-lg transition-all duration-200 transform hover:scale-105 ${
                        isDarkMode 
                          ? 'bg-gray-700 text-gray-300 hover:bg-gray-600' 
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                      }`}
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Navigation Arrows */}
        <button 
          className={`absolute left-2 top-1/2 transform -translate-y-1/2 w-10 h-10 rounded-full shadow-lg flex items-center justify-center transition-all duration-200 z-20 ${
            isDarkMode 
              ? 'bg-gray-800 text-white hover:bg-gray-700 hover:scale-110' 
              : 'bg-white text-gray-800 hover:bg-gray-100 hover:scale-110'
          }`}
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        
        <button 
          className={`absolute right-2 top-1/2 transform -translate-y-1/2 w-10 h-10 rounded-full shadow-lg flex items-center justify-center transition-all duration-200 z-20 ${
            isDarkMode 
              ? 'bg-gray-800 text-white hover:bg-gray-700 hover:scale-110' 
              : 'bg-white text-gray-800 hover:bg-gray-100 hover:scale-110'
          }`}
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </button>
      </section>

      


      
      {/* Modern Categories Section */}



      <section className="mb-16 relative">



        {/* Modern Section Header */}



        <div className="text-center mb-12">



          <div className="inline-block relative group">



            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">



                Shop by Category



              </span>



            </h2>



            {/* Animated Underline - Like Featured Products */}



            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>



          </div>



          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>



            Explore our wide range of fresh dairy products



          </p>



        </div>







        {/* Modern Grid Layout */}



        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-8">



          {categories.map((category) => (



            <Link



              key={category}



              to={`/products?category=${category}`}



              className="group relative block"



            >



              {/* Ultra-Premium Card Container */}



